// Offline qualification of an existing, stopped synthetic exit-network owner.
// Opens the real primary store, independent recovery witness, and signing journal.
static void verify_external_exit_owner(const fs::path& genesis_file,const fs::path& config_file,const fs::path& database){
 const auto config=Json::parse(read(config_file)).at("capella");const auto genesis=Genesis::from_json(Json::parse(read(genesis_file)));
 check(genesis.chain_id==1337&&genesis.consensus=="beacon","external exit verifier requires synthetic Beacon chain");
 const auto& profile=config.at("profile");const auto rules=load_capella_fork_profile(read(profile.at("file").get<std::string>()),unhex(profile.at("sha256").get<std::string>()),u64(quantity(profile.at("maximumBytes"))));
 const auto& l=config.at("limits");auto n=[&](const char* k){return u64(quantity(l.at(k)));};
 const CapellaStoreSnapshotLimits limits{n("envelopeBytes"),n("blocks"),n("messages"),n("equivocations"),n("stateBytes"),n("totalStateBytes"),n("replaySlots"),n("syncTrials")};
 check(fs::is_regular_file(database/"CURRENT")&&fs::is_regular_file(fs::path(config.at("recoveryWitness").get<std::string>())/"CURRENT"),"missing existing owner/witness");
 Blockchain owner(database,genesis);ChainStore witness(config.at("recoveryWitness").get<std::string>());CapellaDurableReactor recovered(owner,rules,limits,witness);
 const auto current=recovered.current();const auto& head=capella_fork_head(*current.state,rules);const auto& final=current.state->blocks.at(current.state->timed.view.finalized.root);const auto& t=rules.transition;
 const auto context=capella_fork_block_context(final.state,final.header,{t.consensus.epoch,t.execution,t.maximum_state_bytes},t.consensus.state);const auto& validator=context.registry.validators.at(0);
 check(Bytes(validator.public_key.begin(),validator.public_key.end())==Key(0).public_key&&validator.exit_epoch<=context.registry.epoch,"wrong key or still-active finalized validator");
 const auto& credentials=validator.withdrawal_credentials;check(credentials[0]==1,"exit credentials not execution address");const auto recipient=hex(Bytes(credentials.begin()+12,credentials.end()));
 check(recipient=="0x000000000000000000000000000000000000002a"&&genesis.state.get(recipient).balance==0,"unexpected fixture recipient");
 Int total=0,final_total=0;size_t capital=0,final_capital=0,payments=0;
 for(Int height=0;height<=head.execution_block.header.number;++height){const auto block=owner.store().block_by_number(height);check(bool(block),"missing canonical withdrawal block");for(const auto& w:block->withdrawals)if(quantity(w.at("validatorIndex"))==0){check(w.at("address")==recipient,"wrong withdrawal credentials");const auto amount=quantity(w.at("amount"));total+=amount*1000000000;++payments;if(amount>Int("30000000000"))++capital;if(height<=final.execution_block.header.number){final_total+=amount*1000000000;if(amount>Int("30000000000"))++final_capital;}}}
 check(capital==1&&final_capital==1&&head.execution_state.get(recipient).balance==total&&final.execution_state.get(recipient).balance==final_total,"reopened withdrawal accounting differs");
 check(owner.tip().header.hash()==head.execution_block.header.hash()&&owner.state().root()==head.execution_state.root()&&owner.finalized_block()->header.hash()==final.execution_block.header.hash(),"reopened execution owner differs from consensus");
 const auto archive=owner.store().fork_checkpoint(genesis.chain_id,genesis.block.header.hash(),limits.envelope_bytes,current.token);check(archive&&Json::parse(archive->snapshot).value("signedExits",Json::array()).empty()&&recovered.pending_exits().empty(),"finalized exit archive not retired");
 bool journal_checked=false;for(const auto& key:config.at("validator").at("keys"))if(quantity(key.at("index"))==0){check(fs::is_regular_file(fs::path(key.at("journal").get<std::string>())/"CURRENT"),"missing signer journal");ChainStore disk(key.at("journal").get<std::string>()),signer_witness(key.at("recoveryWitness").get<std::string>());BeaconSigningJournal journal(disk,genesis.chain_id,genesis.block.header.hash(),context.genesis_root,Key(0).public_key,t.consensus.epoch.ffg.slots_per_epoch,std::nullopt,&signer_witness);const auto proposal=journal.latest_proposal_slot(),vote=journal.latest_attestation_target();check((!proposal||*proposal/t.consensus.epoch.ffg.slots_per_epoch<validator.exit_epoch)&&(!vote||*vote<validator.exit_epoch),"signing continued after exit eligibility ended");journal_checked=true;}
 std::cout<<Json{{"scenario","capella-external-exit-owner"},{"reopenedWithWitness",true},{"ownerCoherent",true},{"capitalPayments",capital},{"finalizedCapitalPayments",final_capital},{"payments",payments},{"balanceWei",total.get_str()},{"finalizedBalanceWei",final_total.get_str()},{"finalizedNumber",quantity(final.execution_block.header.number)},{"finalizedHash",hex(final.execution_block.header.hash())},{"exitEpoch",validator.exit_epoch},{"archiveRetired",true},{"exitedValidatorJournalChecked",journal_checked}}.dump()<<std::endl;
}
